1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "toDisplayName")
23	    @Mapping(target = "initials", source = "owner", qualifiedByName = "toInitials")
24	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "toMembershipNumber")
25	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "toMembershipLevel")
26	    @Mapping(target = "locality", source = "owner", qualifiedByName = "toLocality")
27	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "toContactPreference")
28	    @Mapping(target = "identityKey", source = "owner", qualifiedByName = "toIdentityKey")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /**
32	     * Derives the owner's duplicate-detection {@code identityKey}: the single key that consolidates
33	     * the former separate telephone, email and household checks. It is the owner's normalized
34	     * telephone, its email (lower-cased and trimmed, or the empty string when absent) and its
35	     * household identifier (or the empty string when absent), joined in that order by {@code '|'}.
36	     * Because the telephone is part of the key, two members of the same household with different
37	     * telephones have different identity keys; only an exact full-key match is a duplicate.
38	     */
39	    @Named("toIdentityKey")
40	    default String toIdentityKey(Owner owner) {
41	        if (owner == null) {
42	            return null;
43	        }
44	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
45	        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
46	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
47	        return telephone + "|" + email + "|" + householdId;
48	    }
49	
50	    /**
51	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
52	     * email, otherwise {@code 'PHONE'}.
53	     */
54	    @Named("toContactPreference")
55	    default String toContactPreference(Owner owner) {
56	        if (owner == null) {
57	            return null;
58	        }
59	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
60	        return hasEmail ? "EMAIL" : "PHONE";
61	    }
62	
63	    /**
64	     * Fixed city-to-region table used to derive an owner's locality.
65	     */
66	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
67	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
68	
69	    /**
70	     * Derives the owner's locality as the canonical region for the owner's city from the fixed
71	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
72	     * or {@code 'UNKNOWN'} when the city is not in the table.
73	     */
74	    @Named("toLocality")
75	    default String toLocality(Owner owner) {
76	        if (owner == null) {
77	            return null;
78	        }
79	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
80	    }
81	
82	    /**
83	     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
84	     */
85	    @Named("toDisplayName")
86	    default String toDisplayName(Owner owner) {
87	        if (owner == null) {
88	            return null;
89	        }
90	        return owner.getLastName() + ", " + owner.getFirstName();
91	    }
92	
93	    /**
94	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
95	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
96	     */
97	    @Named("toInitials")
98	    default String toInitials(Owner owner) {
99	        if (owner == null) {
100	            return null;
101	        }
102	        return initial(owner.getFirstName()) + initial(owner.getLastName());
103	    }
104	
105	    /**
106	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
107	     * the last two digits of the {@code registrationDate} year, e.g. {@code 'SYD-SMI-0007-M26'}. Returns
108	     * {@code null} when either the customer code or the registration date is absent.
109	     */
110	    @Named("toMembershipNumber")
111	    default String toMembershipNumber(Owner owner) {
112	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
113	            return null;
114	        }
115	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
116	    }
117	
118	    /**
119	     * Returns the owner's numeric membership level, assigned on creation: starts at {@code 1}, plus
120	     * {@code 1} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
121	     * ({@code namesakeCount} is 0), capped at {@code 3} (level 4 is reserved for tenure).
122	     */
123	    @Named("toMembershipLevel")
124	    default Integer toMembershipLevel(Owner owner) {
125	        if (owner == null) {
126	            return null;
127	        }
128	        int level = 1;
129	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
130	        if (hasEmail) {
131	            level++;
132	        }
133	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
134	        if (noNamesakes) {
135	            level++;
136	        }
137	        return Math.min(level, 3);
138	    }
139	
140	    private static String initial(String name) {
141	        if (name == null || name.isEmpty()) {
142	            return "";
143	        }
144	        return Character.toUpperCase(name.charAt(0)) + ".";
145	    }
146	
147	    Owner toOwner(OwnerDto ownerDto);
148	
149	    @Mapping(target = "id", ignore = true)
150	    @Mapping(target = "pets", ignore = true)
151	    Owner toOwner(OwnerFieldsDto ownerDto);
152	
153	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
154	
155	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
156	
157	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
158	        OwnerPageDto ownerPageDto = new OwnerPageDto();
159	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
160	        ownerPageDto.setPage(ownerPage.getNumber());
161	        ownerPageDto.setSize(ownerPage.getSize());
162	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
163	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
164	        return ownerPageDto;
165	    }
166	}
